record Route(String cidr, String target) {}

static long ip(String s) {
    long v = 0;
    for (String p : s.split("\\.")) v = v << 8 | Integer.parseInt(p);
    return v;
}

static String pick(List<Route> table, String dst) {
    Route best = null; int bestLen = -1;
    for (Route r : table) {
        String[] parts = r.cidr().split("/");
        int len = Integer.parseInt(parts[1]);
        long mask = len == 0 ? 0 : (0xFFFFFFFFL << (32 - len)) & 0xFFFFFFFFL;
        if ((ip(dst) & mask) == (ip(parts[0]) & mask) && len > bestLen) { best = r; bestLen = len; }
    }
    return best.target();
}

public static void main(String[] args) {
    List<Route> table = List.of(
        new Route("10.20.0.0/16", "local"),
        new Route("10.0.0.0/8", "tgw"),
        new Route("0.0.0.0/0", "nat"));
    for (String dst : List.of("10.20.5.9", "10.10.42.15", "52.95.110.1"))
        System.out.print(pick(table, dst) + " ");
}
